133	pub fn load_tools() -> Vec<String> {
134	    if let Ok(path) = env::var("TEA_TOOLS_JSON") {
135	        if let Ok(text) = fs::read_to_string(&path) {
136	            if let Ok(data) = serde_json::from_str::<serde_json::Value>(&text) {
137	                if let Some(obj) = data.as_object() {
138	                    if !obj.is_empty() {
139	                        let mut keys: Vec<String> = obj.keys().cloned().collect();
140	                        keys.sort();
141	                        return keys;
142	                    }
143	                }
144	            }
145	        }
146	    }
147	    FALLBACK_TOOLS.iter().map(|s| (*s).to_string()).collect()
148	}
