150	pub fn config_path() -> PathBuf {
151	    if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
152	        if !xdg.is_empty() {
153	            return PathBuf::from(xdg).join("tea").join("config.toml");
154	        }
155	    }
156	    let home = env::var("HOME").unwrap_or_else(|_| String::from("/"));
157	    PathBuf::from(home).join(".config").join("tea").join("config.toml")
