169	pub fn ensure_user_config() -> io::Result<PathBuf> {
170	    let path = config_path();
171	    if !path.is_file() {
172	        if let Some(parent) = path.parent() {
173	            fs::create_dir_all(parent)?;
174	        }
175	        fs::write(&path, default_config_text())?;
176	    }
177	    Ok(path)
178	}
