180	fn as_bool(val: &toml::Value, default: bool) -> bool {
181	    match val {
182	        toml::Value::Boolean(b) => *b,
183	        toml::Value::Integer(i) => *i != 0,
184	        toml::Value::Float(f) => *f != 0.0,
185	        toml::Value::String(s) => {
186	            let s = s.trim().to_lowercase();
187	            match s.as_str() {
188	                "1" | "true" | "yes" | "on" => true,
189	                "0" | "false" | "no" | "off" => false,
190	                _ => default,
191	            }
192	        }
193	        _ => default,
194	    }
195	}
