197	fn as_int(val: &toml::Value, default: i64) -> i64 {
198	    match val {
199	        toml::Value::Integer(i) => *i,
200	        toml::Value::String(s) => s.trim().parse().unwrap_or(default),
201	        toml::Value::Float(f) => *f as i64,
202	        _ => default,
203	    }
