206	fn apply_raw(base: &ToolCfg, raw: &HashMap<String, toml::Value>) -> ToolCfg {
207	    let mut cfg = base.clone();
208	    let mut raw = raw.clone();
209	    if raw.contains_key("default-intactive") && !raw.contains_key("default-interactive") {
210	        if let Some(v) = raw.remove("default-intactive") {
211	            raw.insert("default-interactive".into(), v);
212	        }
213	    }
214	
215	    if let Some(v) = raw.get("enabled") {
216	        cfg.enabled = as_bool(v, cfg.enabled);
217	    }
218	    if let Some(v) = raw.get("only-in-git-repos") {
219	        cfg.only_in_git_repos = as_bool(v, cfg.only_in_git_repos);
220	    }
221	    if let Some(v) = raw.get("only-outside-git-repos") {
222	        cfg.only_outside_git_repos = as_bool(v, cfg.only_outside_git_repos);
223	    }
224	    if let Some(v) = raw.get("update-gitignore") {
225	        cfg.update_gitignore = as_bool(v, cfg.update_gitignore);
226	    }
227	    if let Some(v) = raw.get("default-interactive") {
228	        cfg.default_interactive = as_bool(v, cfg.default_interactive);
229	    }
230	    if let Some(v) = raw.get("manual-only") {
231	        cfg.manual_only = as_bool(v, cfg.manual_only);
232	    }
233	    if let Some(v) = raw.get("quiet") {
234	        cfg.quiet = as_bool(v, cfg.quiet);
235	    }
236	    if let Some(v) = raw.get("max-log-records") {
237	        cfg.max_log_records = as_int(v, cfg.max_log_records as i64).max(1) as usize;
238	    }
239	    cfg
240	}
