242	pub fn load_config() -> Config {
243	    let path = match ensure_user_config() {
244	        Ok(p) => p,
245	        Err(_) => config_path(),
246	    };
247	    let mut defaults = ToolCfg::default();
248	
249	    let text = fs::read_to_string(&path).unwrap_or_default();
250	    let raw: RawConfig = match toml::from_str(&text) {
251	        Ok(r) => r,
252	        Err(exc) => {
253	            eprintln!("tea: warning: bad config {}: {exc}", path.display());
254	            RawConfig {
255	                defaults: HashMap::new(),
256	                tools: HashMap::new(),
257	            }
258	        }
259	    };
260	
261	    defaults = apply_raw(&defaults, &raw.defaults);
262	
263	    let mut tools_map: HashMap<String, ToolCfg> = HashMap::new();
264	    for name in load_tools() {
265	        let section = raw.tools.get(&name).cloned().unwrap_or_default();
266	        tools_map.insert(name, apply_raw(&defaults, &section));
267	    }
268	
269	    Config {
270	        defaults,
271	        tools: tools_map,
272	        path: path.to_string_lossy().into_owned(),
273	    }
274	}
