323	fn process_cmdline_argv(pid: i32) -> Vec<String> {
324	    let Ok(raw) = fs::read(format!("/proc/{pid}/cmdline")) else {
325	        return Vec::new();
326	    };
327	    raw.split(|b: &u8| *b == 0)
328	        .filter(|s| !s.is_empty())
329	        .filter_map(|s| std::str::from_utf8(s).ok().map(str::to_string))
330	        .collect()
331	}
332	
333	fn process_ppid(pid: i32) -> Option<i32> {
334	    let stat = fs::read_to_string(format!("/proc/{pid}/stat")).ok()?;
335	    let parts: Vec<&str> = stat.split_whitespace().collect();
336	    parts.get(3)?.parse().ok()
337	}
