401	fn shell_level() -> Option<u32> {
402	    env::var("SHLVL").ok().and_then(|v| v.parse().ok())
403	}
404	
405	/// Warp and similar terminals spawn nested shell layers (InitShell bootstrap,
406	/// command substitutions) before running internal sed/tr/od pipelines. User
407	/// pipeline stages inherit SHLVL from the interactive shell (~2–4); internal
408	/// tooling is much deeper (the Warp echo path observed SHLVL=5).
409	fn is_terminal_emulator_deep_subprocess() -> bool {
410	    if !term_program_is_emulator() {
411	        return false;
412	    }
413	    shell_level().is_some_and(|level| level >= 5)
414	}
