422	fn shell_argv_has_dash_c(argv: &[String]) -> bool {
423	    if argv.is_empty() {
424	        return false;
425	    }
426	    if !SHELL_NAMES.iter().any(|s| *s == argv0_base(argv).as_str()) {
427	        return false;
428	    }
429	    argv.iter().any(|a| a == "-c")
430	}
