432	/// True when the immediate parent is the user's shell (or a shell `-c` one
433	/// level below another shell). Terminal emulators' internal `sh -c` pipelines
434	/// (Warp paste handling, etc.) are excluded.
435	pub fn tea_user_pipe_set() -> bool {
436	    env_truthy("TEA_USER_PIPE")
437	}
438	
439	pub fn is_user_pipeline_stage() -> bool {
440	    if tea_user_pipe_set() {
441	        return true;
442	    }
443	
444	    // Under TERM_PROGRAM (Warp, etc.) session fish is the parent of both user
445	    // pipelines and terminal input-engine internals — parent/SHLVL heuristics
446	    // cannot tell them apart. Require the fish hook's TEA_USER_PIPE there.
447	    if term_program_is_emulator() {
448	        return false;
449	    }
450	
451	    let ppid = unsafe { libc::getppid() };
452	    if ppid <= 1 {
453	        return false;
454	    }
455	    let Some(parent_comm) = process_comm(ppid) else {
456	        return false;
457	    };
458	    let parent_argv = process_cmdline_argv(ppid);
459	    let parent_base = argv0_base(&parent_argv);
460	
461	    // Interactive fish (no `-c`) parents tab-completion helpers — e.g.
462	    // `__fish_complete_pids` pipes to `tail -n +2` when completing `kill` —
463	    // that pass parent/TTY heuristics but are not user pipelines. Real fish
464	    // pipes set TEA_USER_PIPE via the vendor_conf.d preexec hook (above).
465	    if parent_comm.trim() == "fish" && !shell_argv_has_dash_c(&parent_argv) {
466	        return false;
467	    }
468	
469	    if is_terminal_emulator_deep_subprocess() {
470	        return false;
471	    }
472	
473	    // Terminal emulators and make/recipes spawn filters via POSIX sh/dash, not
474	    // the user's fish/bash pipeline executor.
475	    if matches!(parent_base.as_str(), "sh" | "dash") {
476	        return false;
477	    }
478	
479	    if !comm_is_shell(&parent_comm) {
480	        return false;
481	    }
482	
483	    if shell_argv_has_dash_c(&parent_argv) {
484	        // Warp uses bash/sh -c for internal pipelines; fish -c is still a user shell.
485	        if term_program_is_emulator() && parent_base != "fish" {
486	            return false;
487	        }
488	        let Some(gppid) = process_ppid(ppid) else {
489	            return false;
490	        };
491	        let Some(gp_comm) = process_comm(gppid) else {
492	            return false;
493	        };
494	        if comm_is_terminal_emulator(&gp_comm) {
495	            return false;
496	        }
497	        return comm_is_shell(&gp_comm);
498	    }
499	    true
500	}
