502	/// Returns true when the immediate parent process is a shell executing a script
503	/// file (e.g. `bash /path/to/nix-scout`). Used to suppress activation for tools
504	/// called from within a script's internals, as opposed to a user or agent typing
505	/// the command directly.
506	pub fn parent_is_running_script() -> bool {
507	    let ppid = unsafe { libc::getppid() };
508	    if ppid <= 1 {
509	        return false;
510	    }
511	    let Ok(raw) = fs::read(format!("/proc/{ppid}/cmdline")) else {
512	        return false;
513	    };
514	    if raw.is_empty() {
515	        return false;
516	    }
517	    let argv: Vec<&str> = raw
518	        .split(|b: &u8| *b == 0)
519	        .filter(|s| !s.is_empty())
520	        .filter_map(|s| std::str::from_utf8(s).ok())
521	        .collect();
522	    if argv.is_empty() {
523	        return false;
524	    }
525	    let argv0_base = Path::new(argv[0])
526	        .file_name()
527	        .and_then(|n| n.to_str())
528	        .unwrap_or("");
529	    if !SHELL_NAMES.iter().any(|s| *s == argv0_base) {
530	        return false;
531	    }
532	    // Walk shell arguments looking for a script-file positional.
533	    // Bail on -c (command string, not a file) or -- (end of options).
534	    let mut i = 1;
535	    while i < argv.len() {
536	        let arg = argv[i];
537	        if arg == "--" {
538	            break;
539	        }
540	        if arg == "-c" {
541	            // Command string follows, not a script path — not a script invocation.
542	            return false;
543	        }
544	        if arg.starts_with('-') {
545	            i += 1;
546	            continue;
547	        }
548	        // First non-flag argument: treat it as the script path.
549	        return Path::new(arg).is_file();
550	    }
551	    false
552	}
