554	fn is_interactive_session_inner(simulate_piped_stdin: bool) -> bool {
555	    if env_truthy("TEA_INTERACTIVE") {
556	        return true;
557	    }
558	    if env::var("CI").map(|v| !v.trim().is_empty()).unwrap_or(false) {
559	        return false;
560	    }
561	    // Stderr being a TTY means we're in a terminal, but that's not enough: stdin
562	    // must also be non-TTY (i.e. actually piped) so we don't activate when a
563	    // subprocess of a non-piped command happens to inherit the terminal.
564	    let stderr_tty = unsafe { libc::isatty(libc::STDERR_FILENO) == 1 };
565	    let stdin_tty = if simulate_piped_stdin {
566	        false
567	    } else {
568	        unsafe { libc::isatty(libc::STDIN_FILENO) == 1 }
569	    };
570	    stderr_tty && !stdin_tty
571	}
572	
573	pub fn is_interactive_session() -> bool {
574	    is_interactive_session_inner(false)
575	}
