674	/// Single activation gate shared by `tea-wrap` and `tea which`.
675	pub fn evaluate_activation(
676	    tool: &str,
677	    cfg: &Config,
678	    force_on: bool,
679	    force_off: bool,
680	    ctx: ActivationContext,
681	) -> ActivationReport {
682	    let tcfg = tool_config(cfg, tool);
683	    let factors = collect_activation_factors(ctx, &tcfg);
684	
685	    if force_off {
686	        return ActivationReport {
687	            activate: false,
688	            outcome: ActivationOutcome::SuppressedForceOff,
689	            factors,
690	        };
691	    }
692	    if force_on {
693	        return ActivationReport {
694	            activate: true,
695	            outcome: ActivationOutcome::ActivatedForceTea,
696	            factors,
697	        };
698	    }
699	    if env_truthy("TEA_OFF") {
700	        return ActivationReport {
701	            activate: false,
702	            outcome: ActivationOutcome::SuppressedTeaOff,
703	            factors,
704	        };
705	    }
706	    if env_truthy("TEA_FORCE") {
707	        return ActivationReport {
708	            activate: true,
709	            outcome: ActivationOutcome::ActivatedTeaForce,
710	            factors,
711	        };
712	    }
713	    if factors.systemd_suppress {
714	        return ActivationReport {
715	            activate: false,
716	            outcome: ActivationOutcome::SuppressedSystemd,
717	            factors,
718	        };
719	    }
720	    if !tcfg.enabled {
721	        return ActivationReport {
722	            activate: false,
723	            outcome: ActivationOutcome::SuppressedDisabled,
724	            factors,
725	        };
726	    }
727	    if tcfg.only_in_git_repos && !factors.in_git_repo {
728	        return ActivationReport {
729	            activate: false,
730	            outcome: ActivationOutcome::SuppressedOnlyInGitRepos,
731	            factors,
732	        };
733	    }
734	    if tcfg.only_outside_git_repos && factors.in_git_repo {
735	        return ActivationReport {
736	            activate: false,
737	            outcome: ActivationOutcome::SuppressedOnlyOutsideGitRepos,
738	            factors,
739	        };
740	    }
741	    if tcfg.manual_only {
742	        return ActivationReport {
743	            activate: false,
744	            outcome: ActivationOutcome::SuppressedManualOnly,
745	            factors,
746	        };
747	    }
748	    if factors.parent_script {
749	        return ActivationReport {
750	            activate: false,
751	            outcome: ActivationOutcome::SuppressedParentScript,
752	            factors,
753	        };
754	    }
755	
756	    if factors.user_pipeline {
757	        if factors.agentic {
758	            return ActivationReport {
759	                activate: true,
760	                outcome: ActivationOutcome::ActivatedAgentic,
761	                factors,
762	            };
763	        }
764	        if factors.default_interactive && factors.interactive_session {
765	            return ActivationReport {
766	                activate: true,
767	                outcome: ActivationOutcome::ActivatedInteractive,
768	                factors,
769	            };
770	        }
771	    }
772	
773	    ActivationReport {
774	        activate: false,
775	        outcome: ActivationOutcome::SuppressedNotAuto,
776	        factors,
777	    }
778	}
