780	pub fn is_agentic() -> bool {
781	    if env_truthy("TEA_AGENT") {
782	        return true;
783	    }
784	    for key in AGENT_ENV_MARKERS {
785	        if let Ok(val) = env::var(key) {
786	            if !env_falsey_or_empty(&val) {
787	                return true;
788	            }
789	        }
790	    }
791	    let mut pid = unsafe { libc::getppid() };
792	    for _ in 0..8 {
793	        if pid <= 1 {
794	            break;
795	        }
796	        if let Ok(comm) = fs::read_to_string(format!("/proc/{pid}/comm")) {
797	            if comm_looks_agent(&comm) {
798	                return true;
799	            }
800	        }
801	        if let Ok(raw) = fs::read(format!("/proc/{pid}/cmdline")) {
802	            let argv0 = raw
803	                .split(|b| *b == 0)
804	                .next()
805	                .and_then(|b| std::str::from_utf8(b).ok())
806	                .unwrap_or("");
807	            let name = Path::new(argv0)
808	                .file_name()
809	                .and_then(|n| n.to_str())
810	                .unwrap_or("");
811	            if basename_looks_agent(name) {
812	                return true;
813	            }
814	        }
815	        let Ok(stat) = fs::read_to_string(format!("/proc/{pid}/stat")) else {
816	            break;
817	        };
818	        let parts: Vec<&str> = stat.split_whitespace().collect();
819	        if parts.len() < 4 {
820	            break;
821	        }
822	        match parts[3].parse::<i32>() {
823	            Ok(ppid) => pid = ppid,
824	            Err(_) => break,
825	        }
826	    }
827	    false
828	}
