949	pub fn discover_pipeline_siblings() -> Vec<(i32, String)> {
950	    let pgid = unsafe { libc::getpgid(0) };
951	    let my_ppid = unsafe { libc::getppid() };
952	    if pgid < 0 {
953	        return Vec::new();
954	    }
955	    let my_pid = process::id() as i32;
956	    let mut found = Vec::new();
957	
958	    let Ok(entries) = fs::read_dir("/proc") else {
959	        return Vec::new();
960	    };
961	    for entry in entries.flatten() {
962	        let name = entry.file_name();
963	        let name = name.to_string_lossy();
964	        if !name.chars().all(|c| c.is_ascii_digit()) {
965	            continue;
966	        }
967	        let Ok(pid) = name.parse::<i32>() else {
968	            continue;
969	        };
970	        let g = unsafe { libc::getpgid(pid) };
971	        if g != pgid {
972	            continue;
973	        }
974	        let Ok(stat) = fs::read_to_string(format!("/proc/{pid}/stat")) else {
975	            continue;
976	        };
977	        let parts: Vec<&str> = stat.split_whitespace().collect();
978	        if parts.len() < 4 {
979	            continue;
980	        }
981	        let Ok(ppid) = parts[3].parse::<i32>() else {
982	            continue;
983	        };
984	        if ppid != my_ppid && pid != my_pid {
985	            continue;
986	        }
987	        let Ok(raw) = fs::read(format!("/proc/{pid}/cmdline")) else {
988	            continue;
989	        };
990	        if raw.is_empty() {
991	            continue;
992	        }
993	        let argv: Vec<String> = raw
994	            .split(|b| *b == 0)
995	            .filter(|p| !p.is_empty())
996	            .map(|p| String::from_utf8_lossy(p).into_owned())
997	            .collect();
998	        if argv.is_empty() {
999	            continue;
1000	        }
1001	        if let Some(display) = display_cmdline(&argv) {
1002	            found.push((pid, display));
1003	        }
1004	    }
1005	    found.sort_by_key(|(pid, _)| *pid);
1006	    found
1007	}
