1009	pub fn highlight_command(
1010	    tool: &str,
1011	    args: &[String],
1012	    siblings: Option<&[(i32, String)]>,
1013	) -> String {
1014	    let stage = format_argv(tool, args);
1015	    let marked = format!("⟦{stage}⟧");
1016	    let owned;
1017	    let sibs = match siblings {
1018	        Some(s) => s,
1019	        None => {
1020	            owned = discover_pipeline_siblings();
1021	            &owned
1022	        }
1023	    };
1024	    if sibs.len() <= 1 {
1025	        return marked;
1026	    }
1027	    let me = process::id() as i32;
1028	    let mut pieces = Vec::new();
1029	    for (pid, cmd) in sibs {
1030	        if *pid == me {
1031	            pieces.push(marked.clone());
1032	        } else {
1033	            pieces.push(cmd.clone());
1034	        }
1035	    }
1036	    if pieces.len() <= 1 {
1037	        return marked;
1038	    }
1039	    pieces.join(" | ")
1040	}
