1042	pub fn ensure_gitignore(cwd: &Path, tcfg: &ToolCfg) {
1043	    if !tcfg.update_gitignore {
1044	        return;
1045	    }
1046	    let Some(root) = git_root(Some(cwd)) else {
1047	        return;
1048	    };
1049	    let gi = root.join(".gitignore");
1050	    let needed = ["logs.csv"];
1051	    let existing = if gi.is_file() {
1052	        fs::read_to_string(&gi).unwrap_or_default()
1053	    } else {
1054	        String::new()
1055	    };
1056	    let present: HashSet<String> = existing
1057	        .lines()
1058	        .map(|ln| ln.trim().to_string())
1059	        .collect();
1060	    let mut to_add = Vec::new();
1061	    for item in needed {
1062	        let mut variants: HashSet<String> = HashSet::new();
1063	        variants.insert(item.to_string());
1064	        variants.insert(format!("/{item}"));
1065	        variants.insert(format!("./{item}"));
1066	        if present.is_disjoint(&variants) {
1067	            to_add.push(item);
1068	        }
1069	    }
1070	    if to_add.is_empty() {
1071	        return;
1072	    }
1073	    let mut f = match OpenOptions::new().create(true).append(true).open(&gi) {
1074	        Ok(f) => f,
1075	        Err(exc) => {
1076	            eprintln!("tea: warning: could not update .gitignore: {exc}");
1077	            return;
1078	        }
1079	    };
1080	    if !existing.is_empty() && !existing.ends_with('\n') {
1081	        let _ = writeln!(f);
1082	    }
1083	    if !present.iter().any(|p| p.contains("# tea")) {
1084	        let _ = writeln!(f, "\n# tea — transparent pipeline logs");
1085	    }
1086	    for item in to_add {
1087	        let _ = writeln!(f, "{item}");
1088	    }
1089	}
