1116	fn parse_csv_rows(raw: &str) -> Vec<CsvRow> {
1117	    let mut rows = Vec::new();
1118	    if raw.trim().is_empty() {
1119	        return rows;
1120	    }
1121	    let mut rdr = csv::ReaderBuilder::new()
1122	        .flexible(true)
1123	        .from_reader(raw.as_bytes());
1124	    let headers: Vec<String> = match rdr.headers() {
1125	        Ok(h) => h.iter().map(|s| s.to_string()).collect(),
1126	        Err(_) => return rows,
1127	    };
1128	    for record in rdr.records().flatten() {
1129	        let mut row = HashMap::new();
1130	        for (i, field) in record.iter().enumerate() {
1131	            if let Some(key) = headers.get(i) {
1132	                row.insert(key.clone(), field.to_string());
1133	            }
1134	        }
1135	        rows.push(row);
1136	    }
1137	    rows
1138	}
