1140	pub fn read_csv_rows(csv_path: &Path) -> Vec<CsvRow> {
1141	    if !csv_path.is_file() {
1142	        return Vec::new();
1143	    }
1144	    let Ok(f) = File::open(csv_path) else {
1145	        return Vec::new();
1146	    };
1147	    flock_sh(f.as_raw_fd());
1148	    let mut raw = String::new();
1149	    let mut fref = &f;
1150	    let _ = fref.read_to_string(&mut raw);
1151	    let rows = parse_csv_rows(&raw);
1152	    flock_un(f.as_raw_fd());
1153	    rows
1154	}
