1156	fn next_id(rows: &[CsvRow]) -> i64 {
1157	    let mut mx = 0i64;
1158	    for row in rows {
1159	        if let Some(id) = row.get("id") {
1160	            if let Ok(n) = id.parse::<i64>() {
1161	                mx = mx.max(n);
1162	            }
1163	        }
1164	    }
1165	    mx + 1
