1168	fn timestamp_now() -> String {
1169	    unsafe {
1170	        let mut t: libc::time_t = 0;
1171	        libc::time(&mut t);
1172	        let tm = libc::localtime(&t);
1173	        if tm.is_null() {
1174	            return "1970-01-01T00:00:00+0000".into();
1175	        }
1176	        let mut buf = [0u8; 64];
1177	        let n = libc::strftime(
1178	            buf.as_mut_ptr() as *mut libc::c_char,
1179	            buf.len(),
1180	            b"%Y-%m-%dT%H:%M:%S%z\0".as_ptr() as *const libc::c_char,
1181	            tm,
1182	        );
1183	        if n == 0 {
1184	            return "1970-01-01T00:00:00+0000".into();
1185	        }
1186	        String::from_utf8_lossy(&buf[..n as usize]).into_owned()
1187	    }
1188	}
