1191	pub fn make_logfile_path() -> io::Result<PathBuf> {
1192	    let output = process::Command::new("mktemp")
1193	        .arg("--suffix")
1194	        .arg(".tea")
1195	        .output()?;
1196	    if !output.status.success() {
1197	        return Err(io::Error::other(format!(
1198	            "mktemp failed: {}",
1199	            String::from_utf8_lossy(&output.stderr)
1200	        )));
1201	    }
