1209	pub fn register_log(
1210	    tool: &str,
1211	    args: &[String],
1212	    logfile: &Path,
1213	    nbytes: u64,
1214	    exit_code: i32,
1215	    tcfg: &ToolCfg,
1216	    cwd: Option<&Path>,
1217	    siblings: Option<&[(i32, String)]>,
1218	) -> io::Result<CsvRow> {
1219	    let cwd = cwd
1220	        .map(Path::to_path_buf)
1221	        .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
1222	    let index_path = csv_path(Some(&cwd));
1223	    ensure_gitignore(&cwd, tcfg);
1224	
1225	    let command = format_argv(tool, args);
1226	    let highlighted = highlight_command(tool, args, siblings);
1227	    let ts = timestamp_now();
1228	
1229	    if let Some(parent) = index_path.parent() {
1230	        fs::create_dir_all(parent)?;
1231	    }
1232	
1233	    let mut f = OpenOptions::new()
1234	        .read(true)
1235	        .write(true)
1236	        .create(true)
1237	        .truncate(false)
1238	        .open(&index_path)?;
1239	    flock_ex(f.as_raw_fd());
1240	
1241	    let result = (|| {
1242	        f.seek(SeekFrom::Start(0))?;
1243	        let mut raw = String::new();
1244	        f.read_to_string(&mut raw)?;
1245	
1246	        let mut rows = parse_csv_rows(&raw);
1247	        let new_id = next_id(&rows);
1248	
1249	        // Captures live under TMPDIR (/tmp); store absolute path.
1250	        let log_stored = logfile
1251	            .canonicalize()
1252	            .unwrap_or_else(|_| logfile.to_path_buf())
1253	            .to_string_lossy()
1254	            .into_owned();
1255	
1256	        let mut row = HashMap::new();
1257	        row.insert("id".into(), new_id.to_string());
1258	        row.insert("timestamp".into(), ts);
1259	        row.insert("cwd".into(), cwd.to_string_lossy().into_owned());
1260	        row.insert("tool".into(), tool.to_string());
1261	        row.insert("command".into(), command);
1262	        row.insert("highlighted".into(), highlighted);
1263	        row.insert("logfile".into(), log_stored);
1264	        row.insert("bytes".into(), nbytes.to_string());
1265	        row.insert("exit_code".into(), exit_code.to_string());
1266	        rows.push(row.clone());
1267	
1268	        let max_n = tcfg.max_log_records.max(1);
1269	        while rows.len() > max_n {
1270	            let old = rows.remove(0);
1271	            if let Some(old_log) = old.get("logfile") {
1272	                if !old_log.is_empty() {
1273	                    let p = {
1274	                        let p = PathBuf::from(old_log);
1275	                        if p.is_absolute() {
1276	                            p
1277	                        } else {
1278	                            cwd.join(p)
1279	                        }
1280	                    };
1281	                    let _ = fs::remove_file(p);
1282	                }
1283	            }
1284	        }
1285	
1286	        f.seek(SeekFrom::Start(0))?;
1287	        f.set_len(0)?;
1288	        {
1289	            let mut wtr = csv::WriterBuilder::new()
1290	                .terminator(csv::Terminator::Any(b'\n'))
1291	                .from_writer(&mut f);
1292	            wtr.write_record(CSV_FIELDS)?;
1293	            for r in &rows {
1294	                let vals: Vec<&str> = CSV_FIELDS
1295	                    .iter()
1296	                    .map(|k| r.get(*k).map(|s| s.as_str()).unwrap_or(""))
1297	                    .collect();
1298	                wtr.write_record(&vals)?;
1299	            }
1300	            wtr.flush()?;
1301	        }
1302	        f.sync_all()?;
1303	        Ok(row)
1304	    })();
1305	
1306	    flock_un(f.as_raw_fd());
1307	    result
1308	}
