1310	pub fn announce(row: &CsvRow, quiet: bool) {
1311	    if quiet || env_truthy("TEA_QUIET") {
1312	        return;
1313	    }
1314	    let id = row.get("id").map(|s| s.as_str()).unwrap_or("?");
1315	    let logfile = row.get("logfile").map(|s| s.as_str()).unwrap_or("?");
1316	    let command = row.get("command").map(|s| s.as_str()).unwrap_or("?");
1317	    eprintln!("[tea] --id {id} {logfile} | {command}");
1318	}
1319	
1320	pub fn list_rows(cwd: Option<&Path>) -> Vec<CsvRow> {
1321	    read_csv_rows(&csv_path(cwd))
1322	}
1323	
1324	pub fn last_row(cwd: Option<&Path>) -> Option<CsvRow> {
1325	    list_rows(cwd).pop()
1326	}
