1328	/// Copy stdin to both the child process stdin and the logfile.
1329	pub fn copy_stdin_to_proc_and_log(
1330	    proc_stdin: &mut impl Write,
1331	    log_f: &mut impl Write,
1332	) -> io::Result<u64> {
1333	    let mut stdin = io::stdin().lock();
1334	    let mut buf = [0u8; 65536];
1335	    let mut nbytes = 0u64;
1336	    loop {
1337	        let n = stdin.read(&mut buf)?;
1338	        if n == 0 {
1339	            break;
1340	        }
1341	        log_f.write_all(&buf[..n])?;
1342	        nbytes += n as u64;
1343	        if let Err(e) = proc_stdin.write_all(&buf[..n]) {
1344	            if e.kind() == io::ErrorKind::BrokenPipe {
1345	                break;
1346	            }
1347	            return Err(e);
1348	        }
1349	    }
1350	    log_f.flush()?;
1351	    Ok(nbytes)
1352	}
