1	//! tea-wrap TOOL REAL_BIN [args...] — transparent tee for pipeline stages.
2	
3	use std::io::{self, Write};
4	use std::os::unix::fs::PermissionsExt;
5	use std::os::unix::process::CommandExt;
6	use std::path::Path;
7	use std::process::{Command, Stdio};
8	
9	use tea::{
10	    announce, copy_stdin_to_proc_and_log, discover_pipeline_siblings, evaluate_activation,
11	    load_config, load_tools, make_logfile_path, register_log, strip_tea_flags, tool_config,
12	    ActivationContext, Config, ToolCfg,
13	};
14	
15	fn passthrough_exec(real: &str, args: &[String]) -> ! {
16	    let err = Command::new(real).args(args).exec();
17	    eprintln!("tea-wrap: exec failed: {err}");
18	    std::process::exit(127);
19	}
20	
21	fn run_wrapped(tool: &str, real: &str, args: &[String], tcfg: &ToolCfg) -> i32 {
22	    let logfile = match make_logfile_path() {
23	        Ok(p) => p,
24	        Err(e) => {
25	            eprintln!("tea-wrap: logfile: {e}");
26	            return 1;
27	        }
28	    };
29	    let quiet = tcfg.quiet;
30	    let siblings = discover_pipeline_siblings();
31	
32	    let mut child = match Command::new(real)
33	        .args(args)
34	        .stdin(Stdio::piped())
35	        .stdout(Stdio::inherit())
36	        .stderr(Stdio::inherit())
37	        .spawn()
38	    {
39	        Ok(c) => c,
40	        Err(e) => {
41	            eprintln!("tea-wrap: spawn {real}: {e}");
42	            return 127;
43	        }
44	    };
45	
46	    let nbytes = {
47	        let mut log_f = match std::fs::OpenOptions::new()
48	            .write(true)
49	            .truncate(true)
50	            .open(&logfile)
51	        {
52	            Ok(f) => f,
53	            Err(e) => {
54	                eprintln!("tea-wrap: open logfile: {e}");
55	                let _ = child.kill();
56	                return 1;
57	            }
58	        };
59	        let mut proc_stdin = child.stdin.take().expect("piped stdin");
60	        match copy_stdin_to_proc_and_log(&mut proc_stdin, &mut log_f) {
61	            Ok(n) => n,
62	            Err(e) if e.kind() == io::ErrorKind::BrokenPipe => {
63	                // Should be rare (copy handles EPIPE on write); keep going.
64	                let _ = log_f.flush();
65	                0
66	            }
67	            Err(e) => {
68	                eprintln!("tea-wrap: copy stdin: {e}");
69	                let _ = child.kill();
70	                return 1;
71	            }
72	        }
73	    };
74	    // Dropping proc_stdin closes the pipe.
75	
76	    let rc = match child.wait() {
77	        Ok(status) => status.code().unwrap_or(1),
78	        Err(_) => 1,
79	    };
80	
81	    match register_log(
82	        tool,
83	        args,
84	        &logfile,
85	        nbytes,
86	        rc,
87	        tcfg,
88	        None,
89	        Some(&siblings),
90	    ) {
91	        Ok(row) => announce(&row, quiet),
92	        Err(e) => eprintln!("tea-wrap: register log: {e}"),
93	    }
94	    rc
95	}
96	
97	fn main() {
98	    let argv: Vec<String> = std::env::args().skip(1).collect();
99	    if argv.len() < 2 {
100	        eprintln!("usage: tea-wrap TOOL REAL_BIN [args...]");
101	        std::process::exit(2);
102	    }
103	
104	    let tool = &argv[0];
105	    let real = &argv[1];
106	    let raw_args = &argv[2..];
107	
108	    let tools = load_tools();
109	    if !tools.iter().any(|t| t == tool) {
110	        eprintln!("tea-wrap: unsupported tool: {tool}");
111	        std::process::exit(2);
112	    }
113	
114	    let real_path = Path::new(real);
115	    let executable = real_path.is_file()
116	        && real_path
117	            .metadata()
118	            .map(|m| m.permissions().mode() & 0o111 != 0)
119	            .unwrap_or(false);
120	    if !executable {
121	        eprintln!("tea-wrap: real binary not executable: {real}");
122	        std::process::exit(127);
123	    }
124	
125	    let (passthrough, force_on, force_off) = strip_tea_flags(raw_args);
126	    let cfg: Config = load_config();
127	    let tcfg = tool_config(&cfg, tool);
128	
129	    let report = evaluate_activation(tool, &cfg, force_on, force_off, ActivationContext::current());
130	    if !report.activate {
131	        passthrough_exec(real, &passthrough);
132	    }
133	
134	    let code = match std::panic::catch_unwind(|| run_wrapped(tool, real, &passthrough, &tcfg)) {
135	        Ok(rc) => rc,
136	        Err(_) => 1,
137	    };
138	
139	    // BrokenPipe on stdout is normal when downstream closes early.
140	    let _ = io::stdout().flush();
141	    std::process::exit(code);
142	}
