input.new_string:
  pkgs = import nixpkgs {
    inherit system;
    overlays = [ inputs.sh-tea.overlays.default ];
  };

  # Host default: don't bother logging auto-activated stages that finish
  # in under 5s — only worth a paper trail if something upstream was
  # actually slow (nix build/eval, nixos-rebuild, ...). Doesn't apply to
  # --tea/TEA_FORCE, which always log regardless of duration.
  configToml = pkgs.writeText "tea-config.toml" ''
    [defaults]
    min-duration-ms = 5000
  '';

  homeFiles = pkgs.runCommand "scout-sh-tea-home" { } ''
    mkdir -p $out/home-files/.config/tea
    cp ${configToml} $out/home-files/.config/tea/config.toml
  '';
in {
  # scout
  # home
  packages.${system}.scout = pkgs.buildEnv {
    name = "scout-sh-tea";
    paths = [
      pkgs.sh-tea
      homeFiles
    ];
    pathsToLink = [ "/bin" "/lib" "/share" "/home-files" ];
  };
}

